prog='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    path = max((v for v in counts if v != bg), key=lambda v: counts[v])
    marker = max((v for v in counts if v not in (bg, path)), key=lambda v: counts[v])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != path or (r,c) in seen:
                continue
            stack = [(r,c)]
            seen.add((r,c))
            comp = []
            while stack:
                x,y = stack.pop()
                comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    xx,yy = x+dx,y+dy
                    if 0 <= xx < h and 0 <= yy < w and grid[xx][yy] == path and (xx,yy) not in seen:
                        seen.add((xx,yy))
                        stack.append((xx,yy))
            comps.append(comp)
    for i, comp in enumerate(comps):
        bottom = max(x for x,y in comp)
        has_lower_path = False
        for j, other in enumerate(comps):
            if i == j or min(x for x,y in other) <= bottom:
                continue
            if any(abs(x-xx) <= 1 and abs(y-yy) <= 1 for x,y in comp for xx,yy in other):
                has_lower_path = True
                break
        if has_lower_path:
            continue
        adjacent = set()
        for x,y in comp:
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    xx,yy = x+dx,y+dy
                    if 0 <= xx < h and 0 <= yy < w and grid[xx][yy] not in (bg,path):
                        adjacent.add((xx,yy))
        if not adjacent:
            continue
        for x,y in comp:
            out[x][y] = 5
        for x,y in adjacent:
            if grid[x][y] == marker:
                out[x][y] = 3
    return out
'''
